import { Scheduler, type Booking, type Slot, type Specialty } from '../../lib'

export function RebookPage(scheduler: Scheduler, previous: Booking, slot: Slot): Booking {
  const book: (patientId: string, slot: Slot, specialty: Specialty) => Booking = scheduler.book.bind(scheduler)
  return book(previous.patientId, slot, previous.specialty)
}
